        card = cards[i]
        counter = 0 
        for j in range(len(cards)):
            next_card = cards[j]
            if(i != j and card == next_card):
                counter += 1
        if(counter >= 1):
            check = True
            for dupli in duplicates:
                if(dupli[0] == card):
                    check = False
            if(check):
